package com.johnny.hotel.pricing; import com.johnny.hotel.entity.SysRole;import com.johnny.hotel.mapper.*;import lombok.RequiredArgsConstructor;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Component;import java.util.Set;import java.util.stream.Collectors;
@Component @RequiredArgsConstructor public class PricingAccess{private final SysUserMapper users;private final SysRoleMapper roles;private Set<String> roles(Long id){var u=users.selectById(id);if(u==null||!Integer.valueOf(1).equals(u.getStatus()))throw denied();return roles.selectRolesByUserId(id).stream().map(SysRole::getRoleCode).collect(Collectors.toSet());}public void read(Long id){var r=roles(id);if(r.stream().noneMatch(Set.of("STAFF","FINANCE","MANAGER","OWNER","SUPER_ADMIN")::contains))throw denied();}public void policyWrite(Long id){var r=roles(id);if(!r.contains("OWNER")&&!r.contains("SUPER_ADMIN"))throw denied();}public void overrideWrite(Long id){var r=roles(id);if(r.stream().noneMatch(Set.of("STAFF","MANAGER","OWNER","SUPER_ADMIN")::contains))throw denied();}private AccessDeniedException denied(){return new AccessDeniedException("Pricing access denied");}}
